"""#

    /// thread.count = {n, plural, one {# thread} other {# threads}}
    static func thread_count(n: Int) -> String { f("thread.count", ["n": String(n)]) }

    /// files.changed = {n, plural, =0 {No files changed} one {# file changed} other {# files changed}}
    static func files_changed(n: Int) -> String { f("files.changed", ["n": String(n)]) }

    /// turn.by = {who, select, you {You} agent {Agent} other {Someone}}
    static func turn_by(who: String) -> String { f("turn.by", ["who": who]) }

    /// thread.delete.ask = Delete {title}?
    static func thread_delete_ask(title: String) -> String { f("thread.delete.ask", ["title": title]) }

    /// settings.tailscale.label = Tailscale: {state}
    static func settings_tailscale_label(state: String) -> String { f("settings.tailscale.label", ["state": state]) }

    /// settings.tailscale.off.note = Listening on {listen} only: started with --no-tailscale.
    static func settings_tailscale_off_note(listen: String) -> String { f("settings.tailscale.off.note", ["listen": listen]) }

    /// settings.tailscale.unavailable.note = Listening on {listen} only. Sign in to Tailscale, then restart Backplane.
    static func settings_tailscale_unavailable_note(listen: String) -> String { f("settings.tailscale.unavailable.note", ["listen": listen]) }

    /// settings.update.available = update {version}
    static func settings_update_available(version: String) -> String { f("settings.update.available", ["version": version]) }

    /// settings.update.waits = Update waits for {count} {plural, select, one {thread} other {threads}} to finish their work.
    static func settings_update_waits(count: String, plural: String) -> String { f("settings.update.waits", ["count": count, "plural": plural]) }

    /// composer.draft.limit = This draft is {size} KB. A message can be at most {limit} KB.
    static func composer_draft_limit(size: String, limit: String) -> String { f("composer.draft.limit", ["size": size, "limit": limit]) }

    /// proj.on = On {name} (change)
    static func proj_on(name: String) -> String { f("proj.on", ["name": name]) }

    /// proj.exists = {dir} is already a project
    static func proj_exists(dir: String) -> String { f("proj.exists", ["dir": dir]) }

    /// proj.add = Add {dir} as a project
    static func proj_add(dir: String) -> String { f("proj.add", ["dir": dir]) }

    /// proj.create = Create project ''{name}'' here
    static func proj_create(name: String) -> String { f("proj.create", ["name": name]) }

    /// proj.mkdir = Create folder ''{name}'' here
    static func proj_mkdir(name: String) -> String { f("proj.mkdir", ["name": name]) }

    /// proj.goto = Go to {path}
    static func proj_goto(path: String) -> String { f("proj.goto", ["path": path]) }

    /// proj.createat = Create project {path}
    static func proj_createat(path: String) -> String { f("proj.createat", ["path": path]) }

    /// proj.addcand = Add {name}
    static func proj_addcand(name: String) -> String { f("proj.addcand", ["name": name]) }

    /// queue.handoff = {first} (goes with the next message)
    static func queue_handoff(first: String) -> String { f("queue.handoff", ["first": first]) }

    /// todos.all = Show all {n}
    static func todos_all(n: String) -> String { f("todos.all", ["n": n]) }

    /// machines.behind = Catching up: {count} {plural, select, one {project} other {projects}} still loading. The rest are ready.
    static func machines_behind(count: String, plural: String) -> String { f("machines.behind", ["count": count, "plural": plural]) }

    /// ask.allow = Allow {tool}?
    static func ask_allow(tool: String) -> String { f("ask.allow", ["tool": tool]) }

    /// apikeys.kept = Agents use these without ever reading them: {n} kept.
    static func apikeys_kept(n: String) -> String { f("apikeys.kept", ["n": n]) }

    /// teach.watching = {name} is watching and learning
    static func teach_watching(name: String) -> String { f("teach.watching", ["name": name]) }

    /// plane.lock.outside = held outside the hub by pid {pid} ({cmd})
    static func plane_lock_outside(pid: String, cmd: String) -> String { f("plane.lock.outside", ["pid": pid, "cmd": cmd]) }

    /// plane.lock.by = held by {title} {ago}
    static func plane_lock_by(title: String, ago: String) -> String { f("plane.lock.by", ["title": title, "ago": ago]) }

    /// plane.lock.row = {name} · {who} · {n} waiting
    static func plane_lock_row(name: String, who: String, n: String) -> String { f("plane.lock.row", ["name": name, "who": who, "n": n]) }

    /// plane.deploy.sub = {line} · Cancel
    static func plane_deploy_sub(line: String) -> String { f("plane.deploy.sub", ["line": line]) }

    /// plane.count.need = {n} need you
    static func plane_count_need(n: String) -> String { f("plane.count.need", ["n": n]) }

    /// plane.count.run = {n} running
    static func plane_count_run(n: String) -> String { f("plane.count.run", ["n": n]) }

    /// plane.count.failed = {n} failed
    static func plane_count_failed(n: String) -> String { f("plane.count.failed", ["n": n]) }

    /// plane.home.line = Home: {name}
    static func plane_home_line(name: String) -> String { f("plane.home.line", ["name": name]) }

    /// sched.done = Done · {when}
    static func sched_done(when: String) -> String { f("sched.done", ["when": when]) }

    /// sched.hint.next = {text} · next {when}
    static func sched_hint_next(text: String, when: String) -> String { f("sched.hint.next", ["text": text, "when": when]) }

    /// sched.hint.once = Once · {when}
    static func sched_hint_once(when: String) -> String { f("sched.hint.once", ["when": when]) }

    /// fold.calls = {count} {plural, select, one {tool call} other {tool calls}}
    static func fold_calls(count: String, plural: String) -> String { f("fold.calls", ["count": count, "plural": plural]) }

    /// fold.steps = {count} {plural, select, one {design change} other {design changes}}
    static func fold_steps(count: String, plural: String) -> String { f("fold.steps", ["count": count, "plural": plural]) }

    /// fold.worked = Worked for {took} · {ago}
    static func fold_worked(took: String, ago: String) -> String { f("fold.worked", ["took": took, "ago": ago]) }

    /// fold.working = Working · started {ago}
    static func fold_working(ago: String) -> String { f("fold.working", ["ago": ago]) }

    /// fold.running = running: {kind}
    static func fold_running(kind: String) -> String { f("fold.running", ["kind": kind]) }

    /// apierr.say = {kind, select, overloaded {Claude's API was overloaded} rate {Claude's API hit its rate limit} server {Claude's API had an internal error} auth {Claude's API refused the sign-in} other {Claude's API answered with an error}}{code} and ended the turn{why}.
    static func apierr_say(kind: String, code: String, why: String) -> String { f("apierr.say", ["kind": kind, "code": code, "why": why]) }

    /// history.step = Step {step}
    static func history_step(step: String) -> String { f("history.step", ["step": step]) }

    /// history.turn = Turn {turn}
    static func history_turn(turn: String) -> String { f("history.turn", ["turn": turn]) }

    /// history.branchpoint = Branch point · {branch}
    static func history_branchpoint(branch: String) -> String { f("history.branchpoint", ["branch": branch]) }

    /// history.position = Step {step} of {total}
    static func history_position(step: String, total: String) -> String { f("history.position", ["step": step, "total": total]) }

